head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


// Avoid `console` errors in browsers that lack a console.
(function() {
    var method;
    var noop = function() {

    };
    var methods = ['assert', 'clear', 'count', 'debug', 'dir', 'dirxml', 'error', 'exception', 'group', 'groupCollapsed', 'groupEnd', 'info', 'log', 'markTimeline', 'profile', 'profileEnd', 'table', 'time', 'timeEnd', 'timeline', 'timelineEnd', 'timeStamp', 'trace', 'warn'];
    var length = methods.length;
    var console = (window.console = window.console || {});
    while (length--) {
        method = methods[length];
        if (!console[method]) {
            console[method] = noop;
        }
    }

}());




// Place any jQuery/helper plugins in here.
(function() {
    $('.bxslider').bxSlider({
        auto: true,
        speed: 800,
        controls: false,
        touchEnabled: false
    });
}());
$(function() {
    var duration = 300;
    var $quickMenu = $('.quickMenu');
    var $quickButton = $quickMenu.find('button');
    $quickButton.on('click', function() {
        $quickMenu.toggleClass('open');
        if ($quickMenu.hasClass('open')) {
            $quickMenu.stop(true).animate({
                right: '0px'
            }, duration, 'easeOutBack');
            $quickButton.find('img').attr('src', '/img/sub/quick/quickMenuClose.png');
        } else {
            $quickMenu.stop(true).animate({
                right: '-120px'
            }, duration, 'easeInBack');
            $quickButton.find('img').attr('src', '/img/sub/quick/quickMenuOpen.png');
        }
    });
});
$(function() {
    var $sfMenu = $('.sf-menu');
    var $sfMenuList = $sfMenu.find('> li');
    $sfMenuList.each(function() {
        $(this).on('mouseover', function() {
            $(this).find('ul').show();
            if ($(this).find('ul').length > 0) $('.sf-menu-subBg').stop(true).animate().show();
        }).on('mouseout', function() {
            /*
            if ($(this).hasClass('gnbCurrent')) {
                $(this).find('ul').show();
                $('.sf-menu-subBg').stop(true).animate().show();
            } else {
                $(this).find('ul').hide();
                $('.sf-menu-subBg').stop(true).animate().hide();
            }
            */
            $(this).find('ul').hide();
            $('.sf-menu-subBg').stop(true).animate().hide();
        });
        /*
        if ($(this).hasClass('gnbCurrent')) {
            $('.sf-menu-subBg').stop(true).animate().show();
            $(this).find('ul').show();
        } else {
            $(this).removeClass('gnbCurrent');
            $(this).find('ul').hide();
            $('.sf-menu-subBg').stop(true).animate().hide();
        }
        */

    });
});
